func test_transpile_TestTranspile_test_error_level(self *Case, a Args) Value {
	var invalid, expected_messages, expected_errors, error_, ctx, more_than_max_errors, logger Value
	_ = []Value{invalid, expected_messages, expected_errors, error_, ctx, more_than_max_errors, logger}
	logger = a.Get(0, "logger", nil)
	logger_restore := func() {}
	logger, logger_restore = self.PatchLogger()
	defer logger_restore()
	self.Do(1102, func() { invalid = "x + 1. (" })
	self.Do(1103, func() {
		expected_messages = NewList("Required keyword: 'expressions' missing for <class 'sqlglot.expressions.core.Aliases'>. Line 1, Col: 8.\n  x + 1. \u001b[4m(\u001b[0m", "Expecting ). Line 1, Col: 8.\n  x + 1. \u001b[4m(\u001b[0m")
	})
	self.Do(1107, func() {
		expected_errors = NewList(NewDict("description", "Required keyword: 'expressions' missing for <class 'sqlglot.expressions.core.Aliases'>", "line", 1, "col", 8, "start_context", "x + 1. ", "highlight", "(", "end_context", "", "into_expression", nil), NewDict("description", "Expecting )", "line", 1, "col", 8, "start_context", "x + 1. ", "highlight", "(", "end_context", "", "into_expression", nil))
	})
	self.Do(1128, func() {
		Call(G("sqlglot.transpile"), invalid, Kw("error_level", A(G("sqlglot.errors.ErrorLevel"), "WARN")))
	})
	for _, item_ := range Iter(expected_messages) {
		error_ = item_
		self.Do(1130, func() { Call(G("tests.helpers.assert_logger_contains"), error_, logger) })
	}
	self.Do(1132, func() {
		self.AssertRaises(func(cm_ Value) {
			ctx = cm_
			Call(G("sqlglot.transpile"), invalid, Kw("error_level", A(G("sqlglot.errors.ErrorLevel"), "IMMEDIATE")))
		}, G("sqlglot.errors.ParseError"))
	})
	self.Do(1135, func() { self.AssertEqual(Str(A(ctx, "exception")), Item(expected_messages, 0)) })
	self.Do(1136, func() { self.AssertEqual(Item(A(A(ctx, "exception"), "errors"), 0), Item(expected_errors, 0)) })
	self.Do(1138, func() {
		self.AssertRaises(func(cm_ Value) {
			ctx = cm_
			Call(G("sqlglot.transpile"), invalid, Kw("error_level", A(G("sqlglot.errors.ErrorLevel"), "RAISE")))
		}, G("sqlglot.errors.ParseError"))
	})
	self.Do(1141, func() { self.AssertEqual(Str(A(ctx, "exception")), M("\n\n", "join", expected_messages)) })
	self.Do(1142, func() { self.AssertEqual(A(A(ctx, "exception"), "errors"), expected_errors) })
	self.Do(1144, func() { more_than_max_errors = "((((" })
	self.Do(1145, func() {
		expected_messages = "Required keyword: 'this' missing for <class 'sqlglot.expressions.core.Paren'>. Line 1, Col: 4.\n  (((\u001b[4m(\u001b[0m\n\nExpecting ). Line 1, Col: 4.\n  (((\u001b[4m(\u001b[0m\n\nExpecting ). Line 1, Col: 4.\n  (((\u001b[4m(\u001b[0m\n\n... and 2 more"
	})
	self.Do(1151, func() {
		expected_errors = NewList(NewDict("description", "Required keyword: 'this' missing for <class 'sqlglot.expressions.core.Paren'>", "line", 1, "col", 4, "start_context", "(((", "highlight", "(", "end_context", "", "into_expression", nil), NewDict("description", "Expecting )", "line", 1, "col", 4, "start_context", "(((", "highlight", "(", "end_context", "", "into_expression", nil))
	})
	self.Do(1172, func() { expected_errors = Add(expected_errors, Mul(NewList(Item(expected_errors, 1)), 3)) })
	self.Do(1174, func() {
		self.AssertRaises(func(cm_ Value) {
			ctx = cm_
			Call(G("sqlglot.transpile"), more_than_max_errors, Kw("error_level", A(G("sqlglot.errors.ErrorLevel"), "RAISE")))
		}, G("sqlglot.errors.ParseError"))
	})
	self.Do(1177, func() { self.AssertEqual(Str(A(ctx, "exception")), expected_messages) })
	self.Do(1178, func() { self.AssertEqual(A(A(ctx, "exception"), "errors"), expected_errors) })
	return nil
}

